import "./AdoptionSearchBar.css";
const AdoptionSearchBar = () => {
  return (
    <div className="search-container">
      <input
        type="text"
        placeholder="Search for an animal..."
        id="search-box"
      />
      <button type="button" className="adoption-button">
        Search
      </button>
    </div>
  );
};
export default AdoptionSearchBar;
